import novamind_api as nm
import json

print("=== Market Overview ===")
try:
    overview = nm.market.get_market_overview()
    print(json.dumps(overview, indent=2))
except Exception as e:
    print(f"Error getting market overview: {e}")

print("\n=== Group Insights S1 ===")
try:
    s1_insights = nm.market.get_group_insights(group_id="S1")
    print(json.dumps(s1_insights, indent=2))
except Exception as e:
    print(f"Error S1: {e}")

print("\n=== Group Insights S3 ===")
try:
    s3_insights = nm.market.get_group_insights(group_id="S3")
    print(json.dumps(s3_insights, indent=2))
except Exception as e:
    print(f"Error S3: {e}")

print("\n=== Active Research Projects ===")
try:
    projects = nm.research.list_research_projects()
    print(json.dumps(projects, indent=2))
except Exception as e:
    print(f"Error list projects: {e}")

