import novamind_api as nm
# Check config overrides or config history
try:
    res = nm.query('SELECT * FROM config_history ORDER BY id DESC LIMIT 20')
    print('Config history:')
    for r in res['rows']:
        print(r)
except Exception as e:
    print('config_history failed:', e)

try:
    res = nm.query('SELECT * FROM config_overrides LIMIT 20')
    print('Config overrides:')
    for r in res['rows']:
        print(r)
except Exception as e:
    print('config_overrides failed:', e)
"

