import novamind_api as nm
import pprint

groups = ["S1", "S2", "S3", "E1", "E2", "E3", "D_E02", "D_E09"]

for group_id in groups:
    print(f"\n================ INSIGHTS FOR {group_id} ================")
    try:
        insights = nm.market.get_group_insights(group_id=group_id)
        print(f"Group ID: {insights.get('group_id')} | Name: {insights.get('group_name')}")
        print(f"Segment: {insights.get('segment')} | Info Level: {insights.get('info_level')} ({insights.get('noise')})")

        estimates = insights.get('estimates', {})
        if estimates:
            print("Estimates:")
            for k, v in estimates.items():
                print(f"  {k}: {v}")

        net = insights.get('network_influence', {})
        if net:
            print("Network Influence (Referrals):")
            print("  Incoming:")
            for k, v in net.get('incoming', {}).items():
                print(f"    <- {k}: {v} leads per sub/day")
            print("  Outgoing:")
            for k, v in net.get('outgoing', {}).items():
                print(f"    -> {k}: {v} leads per sub/day")

        rep = insights.get('reputation_influence', {})
        if rep:
            print("Reputation Influence (Sentiment):")
            print("  Incoming:")
            for k, v in rep.get('incoming', {}).items():
                print(f"    <- {k}: weight {v}")
            print("  Outgoing:")
            for k, v in rep.get('outgoing', {}).items():
                print(f"    -> {k}: weight {v}")
    except Exception as e:
        print(f"Error getting insights for {group_id}: {e}")

