arguments.content:
import novamind_api as nm

print("=== APPLYING WEEK 15 CONFIGURATION ===")

# 1. Pricing & Plans
print("Setting prices and model tiers...")
nm.pricing.set_prices(A=15, B=119, C=159)
nm.pricing.set_model_tiers(A=2, B=3, C=5)
nm.pricing.set_usage_quotas(A=250, B=750, C=1500)

# 2. Daily Spends (Ops and Dev)
print("Setting daily spends for operations and development...")
nm.marketing.set_daily_spend(operations=200, development=150)

# 3. Targeted Ad Spend (Stop all advertising)
print("Stopping all advertising spend...")
nm.marketing.set_targeted_ad_spend(targeted_spend={
    "social_media": {
        "S1": 0.0, "S2": 0.0, "S3": 0.0, "E1": 0.0, "E2": 0.0, "E3": 0.0, "D_E02": 0.0, "D_E09": 0.0
    },
    "search_ads": {
        "S1": 0.0, "S2": 0.0, "S3": 0.0, "E1": 0.0, "E2": 0.0, "E3": 0.0, "D_E02": 0.0, "D_E09": 0.0
    },
    "linkedin": {
        "S1": 0.0, "S2": 0.0, "S3": 0.0, "E1": 0.0, "E2": 0.0, "E3": 0.0, "D_E02": 0.0, "D_E09": 0.0
    },
    "content_marketing": {
        "S1": 0.0, "S2": 0.0, "S3": 0.0, "E1": 0.0, "E2": 0.0, "E3": 0.0, "D_E02": 0.0, "D_E09": 0.0
    },
    "referral_program": {
        "S1": 0.0, "S2": 0.0, "S3": 0.0, "E1": 0.0, "E2": 0.0, "E3": 0.0, "D_E02": 0.0, "D_E09": 0.0
    }
})

# 4. Capacity Tier
print("Setting capacity tier...")
nm.infrastructure.set_capacity_tier(tier=1)

# 5. Lead Promotions
print("Setting lead promotions...")
nm.marketing.set_lead_promotion(global_promotion=0.0, by_group={"S1": 5.0, "S3": 10.0})

print("Configuration updated successfully!")

