import novamind_api as nm

print("Applying Week 27 configurations...")

# 1. Pricing & Plans
nm.pricing.set_prices(A=15.0, B=149.0, C=199.0)
nm.pricing.set_model_tiers(A=3, B=4, C=5)
nm.pricing.set_usage_quotas(A=250, B=750, C=1500)

# 2. Marketing & Spend
nm.marketing.set_daily_spend(operations=100.0, development=0.0)
nm.marketing.set_targeted_ad_spend(targeted_spend={
    "referral_program": {
        "S3": 30.0
    },
    "social_media": {
        "S3": 20.0
    }
})
nm.marketing.set_lead_promotion(global_promotion=0.0, by_group={"S1": 12.0, "S3": 50.0})

# 3. Infrastructure
nm.infrastructure.set_capacity_tier(tier=0)

print("Configurations successfully applied!")

